<?php
namespace App\Filament\Resources\Invoices\Schemas;
use Filament\Forms\Components\DatePicker; use Filament\Forms\Components\DateTimePicker; use Filament\Forms\Components\Select; use Filament\Forms\Components\TextInput; use Filament\Forms\Components\Textarea; use Filament\Forms\Components\Toggle; use Filament\Schemas\Schema;
class InvoiceForm { public static function configure(Schema $schema): Schema { return $schema->components([Select::make('registration_id')->relationship('registration','id')->required(), TextInput::make('invoice_number')->required(), Select::make('type')->options(['deposit'=>'Deposit','final'=>'Final','credit'=>'Credit'])->required(), Select::make('status')->options(['draft'=>'Draft','sent'=>'Sent','paid'=>'Paid','cancelled'=>'Cancelled','credited'=>'Credited'])->required(), TextInput::make('amount_cents')->numeric()->required(), DatePicker::make('due_at'), DateTimePicker::make('sent_at'), DateTimePicker::make('paid_at'), Textarea::make('notes')]); } }
